observation.command:
cd /workspace && curl -s http://localhost:8080/processes -o /tmp/procs.json && (command -v jq >/dev/null && jq -r '.data | group_by(.status)[] | "\(.[0].status): \(length)"' /tmp/procs.json || node -e '
const d=require("/tmp/procs.json").data;
const c={}; d.forEach(p=>c[p.status]=(c[p.status]||0)+1);
console.log("total",d.length,JSON.stringify(c));
d.sort((a,b)=>a.name.localeCompare(b.name)).forEach(p=>console.log(p.status.padEnd(10),"exit="+p.exit_code,"ready="+p.is_ready,"restarts="+p.restarts,p.name));
')
